(async () => {
  const out = {scripts: [...document.querySelectorAll('script[src]')].map(s => s.getAttribute('src'))};
  const probe = document.createElement('canvas');
  out.webgl2 = !!probe.getContext('webgl2');
  out.webgl1 = !!probe.getContext('webgl');
  // does the loader function exist in the loaded file?
  const src = await fetch(out.scripts.find(s => s.includes('main.js'))).then(r => r.text());
  out.hasLoader = src.includes('data-window-gallery');
  out.hasErrCap = src.includes('__wgError');
  return out;
})()
